## Actions, handlers and field events

```jsx
import { useActions, useHandlers, useFieldEvent, useDocumentConfig } from "@loopar/document";

useActions({ export: <Button onClick={exportCsv}>Export</Button> });   // AppBar buttons
useHandlers({ approve: (ctrl) => ctrl.send({ action: "approve" }) });  // JSON buttons: data.action = "approve"
useFieldEvent("customer", "change", (e, ctrl) => ctrl.setValue("discount", 0));
useDocumentConfig({ hasSidebar: false });                              // runtime view flags
```

Layout props do the same declaratively: `<FormLayout actions={{...}} slots={{ totals: () => <Totals/> }} sidebar={...} />`, `<ListLayout columns={[...]} gridTemplate={...} />`.

